/**
 * @brief Extracts the content of the tar file to the given destination path.
 *
 * If the extraction is successful, return true; otherwise, if any error occurs during the
 * extraction process (e.g. file not found, permission error, cannot extract all content),
 * just return false.
 *
 * @param tar_path: the path to the tar file
 * @param dest_path: the path to the destination folder
 *
 * @return true if the extraction is successful; otherwise, false
 */
bool extract_tar_to_path(const std::string& tar_path, const std::string& dest_path) {
    struct archive *src = NULL;
    struct archive *out = NULL;
    struct archive_entry *entry;
    int r;

    // 1. Initialize the archive reader
    src = archive_read_new();
    if (!src) {
        // Failed to initialize archive reader
        return false;
    }

    // Enable support for all compression filters (e.g., gzip, bzip2, xz)
    archive_read_support_filter_all(src);
    // Enable support for all archive formats (e.g., tar, cpio, zip)
    archive_read_support_format_all(src);

    // Open the tar file for reading. A buffer size of 10KB is used.
    r = archive_read_open_filename(src, tar_path.c_str(), 10240);
    if (r != ARCHIVE_OK) {
        // Failed to open the tar file (e.g., file not found, permission error, corrupted file)
        archive_read_free(src); // Clean up the reader structure
        return false;
    }

    // 2. Initialize the archive writer for disk extraction
    // Set flags for extraction options: preserve time, permissions, ACLs, and extended attributes.
    // These flags ensure a more faithful extraction of file attributes from the archive.
    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM | ARCHIVE_EXTRACT_ACL | ARCHIVE_EXTRACT_XATTR;
    out = archive_write_disk_new();
    if (!out) {
        // Failed to initialize archive writer
        archive_read_close(src); // Close the input archive file
        archive_read_free(src);  // Free the input archive structure
        return false;
    }
    archive_write_disk_set_options(out, flags);
    // Enable standard lookup for user/group IDs to set correct ownership.
    // This is important for preserving file ownership if running with appropriate permissions.
    archive_write_disk_set_standard_lookup(out);

    char full_path[4096]; // Buffer for the full destination path. 4KB is generally sufficient.

    // 3. Read and extract each entry from the source archive
    while ((r = archive_read_next_header(src, &entry)) == ARCHIVE_OK) {
        // Construct the full destination path for the current entry.
        // This prepends the dest_path to the entry's original path within the archive.
        // snprintf is used to prevent buffer overflows by truncating if the path is too long.
        snprintf(full_path, sizeof(full_path), "%s/%s",
                 dest_path.c_str(), archive_entry_pathname(entry));

        // Update the entry's pathname to the full destination path for writing to disk.
        // This is crucial for libarchive to write to the correct location.
        archive_entry_set_pathname(entry, full_path);

        // Write the entry's header to disk. This creates directories, sets metadata like permissions, etc.
        r = archive_write_header(out, entry);
        if (r != ARCHIVE_OK) {
            // An error occurred during header writing (e.g., permission denied to create directory/file, invalid path).
            // According to requirements, any error leads to returning false.
            archive_write_free(out);
            archive_read_close(src);
            archive_read_free(src);
            return false;
        }

        // Copy data blocks from the source archive to the disk for regular files.
        // This loop is skipped for directories, symlinks, etc., as they don't have data blocks.
        const void *buff;
        size_t size;
        la_int64_t offset;
        while ((r = archive_read_data_block(src, &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out, buff, size, offset) != ARCHIVE_OK) {
                // An error occurred while writing data block (e.g., disk full, permission denied).
                archive_write_free(out);
                archive_read_close(src);
                archive_read_free(src);
                return false;
            }
        }
        if (r != ARCHIVE_EOF) {
            // An error occurred while reading data block (not just end of file for the current entry).
            // This could indicate a corrupted archive or I/O error.
            archive_write_free(out);
            archive_read_close(src);
            archive_read_free(src);
            return false;
        }

        // Finish the current entry. This is crucial for ensuring all metadata is written and the entry is properly closed on disk.
        // For example, it ensures correct timestamps are set after all data is written.
        r = archive_write_finish_entry(out);
        if (r != ARCHIVE_OK) {
            // An error occurred while finishing the entry (e.g., setting final timestamps or permissions).
            archive_write_free(out);
            archive_read_close(src);
            archive_read_free(src);
            return false;
        }
    }

    // Check the final result of the archive_read_next_header loop.
    // If r is not ARCHIVE_EOF, it means an error occurred during header reading (e.g., corrupted archive structure).
    if (r != ARCHIVE_EOF) {
        archive_write_free(out);
        archive_read_close(src);
        archive_read_free(src);
        return false;
    }

    // 4. Finalize and clean up resources.
    // archive_write_free also closes the output archive and frees its resources.
    archive_write_free(out);
    archive_read_close(src); // Close the input archive file.
    archive_read_free(src);  // Free the input archive structure.

    return true; // All content extracted successfully.
}
